import androidx.compose.ui.unit.dp
import androidx.core.content.ContextCompat
import androidx.lifecycle.compose.LocalLifecycleOwner
import com.project.apppetstore.utils.createImageOnPhotosFolder
import com.project.apppetstore.utils.MultimediaErrorHandler
import kotlinx.coroutines.flow.MutableStateFlow

const val TAG = "CameraComponent"

@Composable
fun CameraComponent(
    modifier: Modifier = Modifier,
    onPhotoTaken: (Uri) -> Unit,
    onCaptureError: ((MultimediaErrorHandler.MultimediaError) -> Unit)? = null
) {
    val context = LocalContext.current
    val lifecycleOwner = LocalLifecycleOwner.current

    val surfaceRequests = remember { MutableStateFlow<SurfaceRequest?>(null) }
    val surfaceRequest by surfaceRequests.collectAsState(initial = null)
    var imageCapture by remember { mutableStateOf<ImageCapture?>(null) }
    var errorMessage by remember { mutableStateOf<Pair<String, String>?>(null) } // (title, message)

    var useFront by rememberSaveable { mutableStateOf(false) }
    val selector = if (useFront) {
        CameraSelector.DEFAULT_FRONT_CAMERA
    } else {
        CameraSelector.DEFAULT_BACK_CAMERA
    }

    LaunchedEffect(selector) {
        val provider = ProcessCameraProvider.awaitInstance(context)
        val preview = Preview.Builder().build().apply {
            setSurfaceProvider { req -> surfaceRequests.value = req }
        }

        imageCapture = ImageCapture.Builder()
            .setCaptureMode(ImageCapture.CAPTURE_MODE_MINIMIZE_LATENCY)
            .build()

        provider.unbindAll()
        provider.bindToLifecycle(
            lifecycleOwner,
            selector,
            preview,
            imageCapture!!,
        )
    }

    Box(modifier) {
        surfaceRequest?.let { req ->
            CameraXViewfinder(
                surfaceRequest = req,
                modifier = Modifier.fillMaxSize()
            )
        }

        FloatingActionButton(
            onClick = { useFront = !useFront },
            modifier = Modifier
                .align(Alignment.TopStart)
                .padding(16.dp)
        ) {
            Icon(
                imageVector = Icons.Rounded.Cameraswitch,
                contentDescription = "Cambiar camara"
            )
        }

        FloatingActionButton(
            onClick = {
                capturePhoto(
                    context = context,
                    imageCapture = imageCapture,
                    onPhotoTaken = onPhotoTaken,
                    onCaptureError = { error ->
                        MultimediaErrorHandler.logDetailed("CameraComponent", error)
                        errorMessage = error.message to error.friendlyMessage
                        onCaptureError?.invoke(error)
                    }
                )
            },
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .padding(16.dp)
        ) {
            Icon(
                imageVector = Icons.Rounded.Camera,
                contentDescription = "Tomar foto"
            )
        }

        // Mostrar error si lo hay
        errorMessage?.let { (title, msg) ->
            Box(
                modifier = Modifier
                    .align(Alignment.Center)
                    .padding(20.dp)
                    .fillMaxSize()
            ) {
                Column(
                    modifier = Modifier.align(Alignment.Center),
                    horizontalAlignment = Alignment.CenterHorizontally
                ) {
                    Text("⚠️", style = MaterialTheme.typography.displayLarge)
                    Text(
                        text = title,
                        style = MaterialTheme.typography.titleMedium
                    )
                    Text(
                        text = msg,
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.error
                    )
                }
            }
        }
    }
}

@Deprecated("Use CameraComponent")
@Composable
fun CameraComponen(modifier: Modifier = Modifier, onPhotoTaken: (Uri) -> Unit) {
    CameraComponent(modifier = modifier, onPhotoTaken = onPhotoTaken)
