package com.project.apppetstore.utils

import android.content.Context
import android.net.Uri
import android.util.Log
import androidx.camera.core.ImageCaptureException
import java.io.File

/**
 * Manejo centralizado de errores multimedia (foto, video, audio)
 * con diagnóstico y fallbacks automáticos.
 */
object MultimediaErrorHandler {

    private const val TAG = "MultimediaErrorHandler"

    sealed class MultimediaError(val message: String, val friendlyMessage: String) {
        // Errores de cámara
        data class CameraNotAvailable(val details: String = "") : MultimediaError(
            "Camera not available",
            "La cámara no está disponible en este dispositivo"
        )
        data class CameraPermissionDenied(val details: String = "") : MultimediaError(
            "Camera permission denied",
            "Se necesita permiso para usar la cámara"
        )
        data class PhotoCaptureFailed(val details: String = "") : MultimediaError(
            "Photo capture failed",
            "No se pudo capturar la foto. Verifica el almacenamiento"
        )
        data class InvalidPhotoUri(val details: String = "") : MultimediaError(
            "Invalid photo URI",
            "La foto no se guardó correctamente"
        )

        // Errores de upload
        data class UploadFailed(val details: String = "") : MultimediaError(
            "Upload failed",
            "Error al subir el archivo a Firebase. Verifica tu conexión"
        )
        data class UploadCancelled(val details: String = "") : MultimediaError(
            "Upload cancelled by user",
            "Descarga cancelada"
        )
        data class StorageQuotaExceeded(val details: String = "") : MultimediaError(
            "Storage quota exceeded",
            "No hay espacio en el almacenamiento del dispositivo"
        )
        data class FileTooLarge(val fileSizeMB: Double) : MultimediaError(
            "File too large: ${fileSizeMB}MB",
            "El archivo es demasiado grande. Máximo 10MB"
        )

        // Errores de galería/picker
        data class PickerFailed(val details: String = "") : MultimediaError(
            "Picker failed",
            "No se pudo abrir el selector de archivos"
        )
        data class InvalidFile(val details: String = "") : MultimediaError(
            "Invalid file",
            "El archivo seleccionado no es válido"
        )

        // Errores de grabación
        data class RecordingFailed(val details: String = "") : MultimediaError(
            "Recording failed",
            "Error al grabar. Intenta nuevamente"
        )
        data class RecordingPermissionDenied(val details: String = "") : MultimediaError(
            "Recording permission denied",
            "Se necesita permiso para grabar audio/video"
        )

        // Error genérico
        data class Unknown(val details: String = "") : MultimediaError(
            "Unknown error",
            "Algo salió mal con la multimedia. Intenta nuevamente"
        )
    }

    /**
     * Procesa excepciones de CameraX y devuelve un [MultimediaError] amigable
     */
    fun handleCameraException(exception: ImageCaptureException): MultimediaError {
        Log.e(TAG, "Camera capture error: ${exception.message}", exception)

        return when (exception.imageCaptureError) {
            ImageCaptureException.ERROR_CAMERA_CLOSED -> 
                CameraNotAvailable("Cámara cerrada inesperadamente")
            ImageCaptureException.ERROR_CAPTURE_FAILED -> 
                PhotoCaptureFailed(exception.message ?: "Capture failed")
            ImageCaptureException.ERROR_FILE_IO -> 
                PhotoCaptureFailed("Error de escritura en almacenamiento")
            ImageCaptureException.ERROR_INVALID_CAMERA -> 
                CameraNotAvailable("Cámara no válida")
            else -> Unknown(exception.message ?: "Unknown camera error")
        }
    }

    /**
     * Valida que el archivo sea válido y tenga un tamaño aceptable (max 10MB)
     */
    fun validateMediaFile(uri: Uri?, context: Context, maxSizeMB: Int = 10): MultimediaError? {
        if (uri == null) {
            return InvalidFile("URI es nulo")
        }

        try {
            val file = File(uri.path ?: return InvalidFile("Ruta de archivo inválida"))

            if (!file.exists()) {
                return InvalidFile("El archivo no existe")
            }

            val fileSizeMB = file.length() / (1024.0 * 1024.0)
            if (fileSizeMB > maxSizeMB) {
                return FileTooLarge(fileSizeMB)
            }

            return null // Todo OK
        } catch (e: Exception) {
            Log.e(TAG, "Error validating file", e)
            return InvalidFile(e.message ?: "Error desconocido")
        }
    }

    /**
     * Procesa errores de upload a Firebase
     */
    fun handleUploadException(exception: Exception): MultimediaError {
        Log.e(TAG, "Upload error: ${exception.message}", exception)

        val message = exception.message ?: ""
        return when {
            message.contains("quota", ignoreCase = true) ->
                StorageQuotaExceeded(message)
            message.contains("cancelled", ignoreCase = true) ||
            message.contains("cancel", ignoreCase = true) ->
                UploadCancelled(message)
            message.contains("offline", ignoreCase = true) ||
            message.contains("network", ignoreCase = true) ->
                UploadFailed("Sin conexión a internet")
            message.contains("unauthorized", ignoreCase = true) ||
            message.contains("permission", ignoreCase = true) ->
                UploadFailed("Permiso denegado para subir archivos")
            else -> UploadFailed(message)
        }
    }

    /**
     * Log detallado para debugging
     */
    fun logDetailed(context: String, error: MultimediaError, exception: Exception? = null) {
        val fullMessage = """
            ====== MULTIMEDIA ERROR ======
            Context: $context
            Error: ${error.message}
            Friendly: ${error.friendlyMessage}
            ${if (exception != null) "Exception: ${exception.javaClass.simpleName}" else ""}
            ${if (exception != null) "Details: ${exception.message}" else ""}
            ==============================
        """.trimIndent()
        Log.e(TAG, fullMessage)
    }

    /**
     * Log de éxito
     */
    fun logSuccess(context: String, fileType: String, fileSizeMB: Double = 0.0) {
        Log.d(TAG, "✓ [$context] $fileType uploaded successfully (${String.format("%.2f", fileSizeMB)} MB)")
    }
}
